package net.civeira.phylax.feature.access.userinvitation.domain.gateway;

import java.util.List;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.feature.identity.tenant.domain.TenantReference;
import net.civeira.phylax.feature.identity.user.domain.UserReference;

class UserInvitationFilterUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test a entity reference contruction")
  void test_user_invitation_filter_builder() {
    UserInvitationFilter filter = UserInvitationFilter.builder().build();
    Assertions.assertFalse(filter.getUid().isPresent(),
        "Uid must be empty if filter is build without it");
    filter.setUid("one");
    Assertions.assertEquals("one", filter.getUid().get(), "Uid must be the same as the assigned");
    Assertions.assertTrue(filter.getUids().isEmpty(),
        "Uid must be empty if filter is build without it");
    filter.setUids(List.of("one"));
    Assertions.assertEquals(List.of("one"), filter.getUids(),
        "Uids must be the same as the assigned");
    Assertions.assertFalse(filter.getSearch().isPresent(),
        "Search must be empty if filter is build without it");
    filter.setSearch("lookup");
    Assertions.assertEquals("lookup", filter.getSearch().get(),
        "Search must be the same as the assigned");
    Assertions.assertFalse(filter.getStatus().isPresent(),
        "Status must be empty if filter is build without it");
    filter.setStatus(null);
    Assertions.assertFalse(filter.getStatus().isPresent(),
        "Status must be the same as the assigned");
    Assertions.assertFalse(filter.getEmail().isPresent(),
        "Email must be empty if filter is build without it");
    filter.setEmail("one");
    Assertions.assertEquals("one", filter.getEmail().get(),
        "Email must be the same as the assigned");
    Assertions.assertFalse(filter.getTenant().isPresent(),
        "Tenant must be empty if filter is build without it");
    filter.setTenant(TenantReference.of("$ref"));
    Assertions.assertEquals(TenantReference.of("$ref"), filter.getTenant().get(),
        "Tenant must be the same as the assigned");
    Assertions.assertTrue(filter.getTenants().isEmpty(),
        "Tenants must be empty if filter is build without it");
    filter.setTenants(List.of("one"));
    Assertions.assertEquals(List.of("one"), filter.getTenants(),
        "Tenants must be the same as the assigned");
    Assertions.assertFalse(filter.getInvitedBy().isPresent(),
        "InvitedBy must be empty if filter is build without it");
    filter.setInvitedBy(UserReference.of("$ref"));
    Assertions.assertEquals(UserReference.of("$ref"), filter.getInvitedBy().get(),
        "InvitedBy must be the same as the assigned");
    Assertions.assertTrue(filter.getInvitedBies().isEmpty(),
        "InvitedBies must be empty if filter is build without it");
    filter.setInvitedBies(List.of("one"));
    Assertions.assertEquals(List.of("one"), filter.getInvitedBies(),
        "InvitedBies must be the same as the assigned");
    Assertions.assertFalse(filter.getAcceptedBy().isPresent(),
        "AcceptedBy must be empty if filter is build without it");
    filter.setAcceptedBy(UserReference.of("$ref"));
    Assertions.assertEquals(UserReference.of("$ref"), filter.getAcceptedBy().get(),
        "AcceptedBy must be the same as the assigned");
    Assertions.assertTrue(filter.getAcceptedBies().isEmpty(),
        "AcceptedBies must be empty if filter is build without it");
    filter.setAcceptedBies(List.of("one"));
    Assertions.assertEquals(List.of("one"), filter.getAcceptedBies(),
        "AcceptedBies must be the same as the assigned");
    Assertions.assertFalse(filter.getTenantAccessible().isPresent(),
        "TenantAccessible must be empty if filter is build without it");
    filter.setTenantAccessible("one");
    Assertions.assertEquals("one", filter.getTenantAccessible().get(),
        "TenantAccessible must be the same as the assigned");
  }
}
